<?php $agents=$edgeAgents??[];$archives=$edgeArchives??[];$token=$newEdgePairingToken??null;$fmt=static function($b){$b=(int)$b;return $b>=1048576?number_format($b/1048576,1,',','.').' MB':($b>=1024?number_format($b/1024,1,',','.').' KB':$b.' B');}; ?>
<div class="d-flex flex-wrap justify-content-between align-items-start gap-2 mb-3"><div><h4 class="mb-1"><i class="bi bi-router me-2"></i>Property Edge Agents</h4><p class="text-body-secondary mb-0">Sondas locales vinculadas a <strong><?=e((string)config('app.instance_name'))?></strong>. Un solo PHEDGE vincula el Agent con este Node; Central queda detrás de la cadena de distribución.</p></div><span class="badge text-bg-primary"><?=e((string)config('app.instance_code'))?></span></div>
<?php if(is_array($token)):?><div class="alert alert-warning"><strong>PHEDGE único generado.</strong> Se muestra una sola vez y vence <?=e(format_datetime_es((string)$token['expires_at']))?>. Central ya preparó la credencial de <code><?=e((string)$token['agent_code'])?></code>.<div class="input-group mt-2"><input class="form-control font-monospace" readonly value="<?=e((string)$token['token'])?>"><button class="btn btn-outline-secondary" type="button" onclick="navigator.clipboard.writeText(this.previousElementSibling.value)"><i class="bi bi-copy"></i></button></div><small class="d-block mt-2">En el Agent solo debe indicar la URL de este Property Node y este PHEDGE; no necesita generar otro BHR en Central.</small></div><?php endif;?>
<div class="card mb-3"><div class="card-header"><strong>Nuevo emparejamiento</strong><small class="d-block text-body-secondary">El Property Node genera la identidad local del Agent. El PHEDGE no contiene credenciales de Central.</small></div><div class="card-body"><form method="post" action="<?=url('edge-agent-create-token')?>" class="row g-3 align-items-end"><?=csrf_field()?><div class="col-md-4"><label class="form-label">Código único del Agent</label><input class="form-control" name="allowed_agent_code" value="<?=e((string)config('app.instance_code'))?>-EDGE-01" required></div><div class="col-md-5"><label class="form-label">Nombre del Agent</label><input class="form-control" name="agent_name" value="<?=e((string)config('app.instance_name'))?> - Edge principal" required></div><div class="col-md-3"><button class="btn btn-primary w-100"><i class="bi bi-key me-2"></i>Generar PHEDGE</button></div></form></div></div>
<div class="card mb-3"><div class="card-header"><strong>Agents vinculados</strong><small class="d-block text-body-secondary">El Agent inicia las conexiones desde la LAN; no necesita IP pública.</small></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Agent</th><th>Versión</th><th>Estado</th><th>Último contacto</th><th>Backups en Node</th><th>Último backup</th></tr></thead><tbody><?php foreach($agents as $a):?><tr><td><strong><?=e((string)$a['agent_name'])?></strong><small class="d-block"><code><?=e((string)$a['agent_code'])?></code> · <?=e((string)($a['base_url']??''))?></small></td><td>v<?=e((string)$a['app_version'])?></td><td><span class="badge text-bg-<?=($a['status']??'')==='active'?'success':'warning'?>"><?=e((string)$a['status'])?></span></td><td><?=e(!empty($a['last_seen_at'])?format_datetime_es((string)$a['last_seen_at']):'Nunca')?></td><td><?=(int)($a['backup_count']??0)?></td><td><?=e(!empty($a['last_backup_at'])?format_datetime_es((string)$a['last_backup_at']):'Nunca')?></td></tr><?php endforeach;?><?php if(!$agents):?><tr><td colspan="6" class="text-center text-body-secondary py-4">Todavía no hay Edge Agents emparejados.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card"><div class="card-header"><strong>Respaldos de Agents custodiados por este Node</strong></div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Recibido</th><th>Agent</th><th>Archivo</th><th>Tamaño</th><th>SHA-256</th><th></th></tr></thead><tbody><?php foreach($archives as $a):?><tr><td><?=e(format_datetime_es((string)$a['received_at']))?></td><td><code><?=e((string)$a['agent_code'])?></code></td><td><?=e((string)$a['filename'])?></td><td><?=$fmt($a['size_bytes'])?></td><td><code><?=e(substr((string)$a['sha256'],0,16))?>…</code></td><td class="text-end"><a class="btn btn-sm btn-outline-secondary" href="<?=url('edge-agent-backup-download',['id'=>(int)$a['id']])?>"><i class="bi bi-download"></i></a></td></tr><?php endforeach;?><?php if(!$archives):?><tr><td colspan="6" class="text-center text-body-secondary py-4">El Node todavía no ha recibido respaldos de Agents.</td></tr><?php endif;?></tbody></table></div></div>
